def comps(g):
    H=len(g);W=len(g[0]);seen=[[False]*W for _ in range(H)];cs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                st=[(i,j)];cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells or not g[a][b]:continue
                    cells.add((a,b))
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            x,y=a+di,b+dj
                            if 0<=x<H and 0<=y<W and g[x][y]:st.append((x,y))
                cs.append(cells)
    return cs
