def make_placements(crop=False):
    # trominoes: color = missing corner of their 2x2 box
    base=[(0,0),(0,1),(1,0),(1,1)]
    P=[]
    for miss in [(0,0),(1,0),(0,1),(1,1)]:
        c={'0':1,'1':2,'2':3,'3':4}[miss[0]+'%d'%miss[1]]
        for i in range(7-crop and 6 or 8):
            for j in range(7-crop and 6 or 8):
                cs={(i+a,j+b) for a,b in base if (a,b)!=miss}
                if crop:
                    cs={c_ for c_ in cs if 0<=c_[0]<7 and 0<=c_[1]<7}
                else:
                    if any(not(0<=c_[0]<7 and 0<=c_[1]<7) for c_ in cs): continue
                P.append((c,frozenset(cs)))
    for i in range(6):
        for j in range(6):
            P.append((1,frozenset([(i,j),(i,j+1),(i+1,j),(i+1,j+1)])))
    return P

def solve(pts, P, maxsols=50, use_clipping=False):
    sols=[]
    S=set()
    for p in P: S|=p[1]
    def rec(rem, sol):
        if len(sols)>=maxsols: return
        if not rem:
            sols.append(list(sol)); return
        for col,cs in P:
            ic={c_ for c_ in cs if 0<=c_[0]<7 and 0<=c_[1]<7}
            if use_clipping and len(ic)&len(cs-ic)<=0 and ic<=rem:
                pass
        # non-clipping: full piece inside rem
        for col,cs in P:
            if cs<=rem:
                rec(set(rem)-cs, sol+[col])
                if len(sols)>=maxsols: return
    rec(set(pts), [])
    return sols

for clip in [False,True]:
    print('--- clipping:',clip)
    for p in [1,2,3]:
        ik=G[f'Demo pair {p} input']; okout=G[f'Demo pair {p} output']
        pts=set((i,j) for i in range(7) for j in range(7) if ik[i][j])
        P=make_placements(crop=(not clip))
        sols=solve(pts,P,maxsols=50000)
        good=[sol for sol in sols if all(okout[i][j]==sol[i][j] for i in range(7) for j in range(7))]
        print('demo',p,'sols:',len(sols),'exact matches:',len(good))

